import z3

def solve_sgp(weeks, groups, group_size):
    num_golfers = groups * group_size

    # X[w][g][p] = 1 if golfer p is in group g in week w
    X = [[[z3.Bool(f"x_{w}_{g}_{p}") for p in range(num_golfers)] for g in range(groups)] for w in range(weeks)]

    s = z3.Solver()

    # Each golfer is in exactly one group per week
    for w in range(weeks):
        for p in range(num_golfers):
            s.add(z3.PbEq([(X[w][g][p], 1) for g in range(groups)], 1))

    # Each group has exactly group_size golfers
    for w in range(weeks):
        for g in range(groups):
            s.add(z3.PbEq([(X[w][g][p], 1) for p in range(num_golfers)], group_size))

    # No two golfers in the same group more than once
    for p1 in range(num_golfers):
        for p2 in range(p1 + 1, num_golfers):
            # They are in the same group in week w if sum_g (X[w][g][p1] AND X[w][g][p2]) == 1
            # We want sum_w sum_g (X[w][g][p1] AND X[w][g][p2]) <= 1
            same_group_vars = []
            for w in range(weeks):
                for g in range(groups):
                    same_group_vars.append(z3.And(X[w][g][p1], X[w][g][p2]))
            s.add(z3.PbLe([(v, 1) for v in same_group_vars], 1))

    # Symmetry breaking
    # Week 0: golfer p is in group p // group_size
    for p in range(num_golfers):
        s.add(X[0][p // group_size][p])

    # Golfer 0 is always in group 0
    for w in range(1, weeks):
        s.add(X[w][0][0])

    # Group ordering in week w: golfer i is in group i for i < groups
    # Wait, golfer 0 is in group 0. Golfer 1 is in group 0 or 1.
    # Let's just order the first element of each group.

    print("Solving...")
    if s.check() == z3.sat:
        m = s.model()
        res = []
        for w in range(weeks):
            for p in range(num_golfers):
                for g in range(groups):
                    if m.evaluate(X[w][g][p]):
                        res.append(g)
        print("SAT")
        print(res)
    else:
        print("UNSAT")

