def verify(sol, weeks, groups, group_size):
    num_golfers = groups * group_size
    pairs = set()
    for w in range(weeks):
        week_sol = sol[w*num_golfers : (w+1)*num_golfers]
        for g in range(groups):
            group_members = [p for p in range(num_golfers) if week_sol[p] == g]
            if len(group_members) != group_size:
                print(f"Week {w} group {g} has {len(group_members)} members")
                return False
            for i in range(len(group_members)):
                for j in range(i+1, len(group_members)):
                    p1, p2 = group_members[i], group_members[j]
                    if p1 > p2: p1, p2 = p2, p1
                    if (p1, p2) in pairs:
                        print(f"Pair {p1}, {p2} repeated in week {w}")
                        return False
                    pairs.add((p1, p2))
    print("Valid!")
    return True

